package com.ledgerly;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.*;import java.util.*;import java.util.stream.*;
@RestController @RequestMapping("/api") class ApiController {
 private final UserRepository users;private final TransactionRepository txs;private final BudgetRepository budgets;private final PasswordEncoder encoder;@Value("${app.jwt.secret}")String secret;
 ApiController(UserRepository u,TransactionRepository t,BudgetRepository b,PasswordEncoder e){users=u;txs=t;budgets=b;encoder=e;}
 record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=8)String password){} record Login(@Email @NotBlank String email,@NotBlank String password){} record AuthUser(Long id,String name,String email){} record AuthResponse(String token,AuthUser user){} record TxRequest(@NotNull @DecimalMin("0.01") BigDecimal amount,@Pattern(regexp="EXPENSE|INCOME")String type,@NotBlank String category,@NotNull LocalDate date,String description){} record BudgetRequest(@NotBlank String month,@NotNull @DecimalMin("0")BigDecimal amount){}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","ok","app","Ledgerly API");}
 @PostMapping("/auth/register") ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.existsByEmailIgnoreCase(r.email()))return ResponseEntity.badRequest().body(Map.of("message","An account with this email already exists."));UserEntity u=users.save(new UserEntity(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password())));return ResponseEntity.ok(authResponse(u));}
 @PostMapping("/auth/login") ResponseEntity<?> login(@Valid @RequestBody Login r){UserEntity u=users.findByEmailIgnoreCase(r.email().trim()).orElse(null);if(u==null||!encoder.matches(r.password(),u.passwordHash))return ResponseEntity.status(401).body(Map.of("message","Email or password is incorrect."));return ResponseEntity.ok(authResponse(u));}
 AuthResponse authResponse(UserEntity u){String token=Jwts.builder().subject(u.id.toString()).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofDays(7)))).signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).compact();return new AuthResponse(token,new AuthUser(u.id,u.name,u.email));}
 Long uid(Authentication a){return Long.valueOf(a.getName());} UserEntity me(Authentication a){return users.findById(uid(a)).orElseThrow();}
 Map<String,Object> txMap(TransactionEntity t){return Map.of("id",t.id,"amount",t.amount,"type",t.type,"category",t.category,"date",t.date,"description",t.description==null?"":t.description);}
 @GetMapping("/transactions") List<Map<String,Object>> transactions(Authentication a){return txs.findByUserIdOrderByDateDescIdDesc(uid(a)).stream().map(this::txMap).toList();}
 @PostMapping("/transactions") ResponseEntity<?> add(@Valid @RequestBody TxRequest r,Authentication a){TransactionEntity t=new TransactionEntity();t.user=me(a);t.amount=r.amount();t.type=r.type();t.category=r.category().trim();t.date=r.date();t.description=r.description()==null?"":r.description().trim();return ResponseEntity.ok(txMap(txs.save(t)));}
 @DeleteMapping("/transactions/{id}") ResponseEntity<?> delete(@PathVariable Long id,Authentication a){var t=txs.findByIdAndUserId(id,uid(a));if(t.isEmpty())return ResponseEntity.notFound().build();txs.delete(t.get());return ResponseEntity.noContent().build();}
 @GetMapping("/budget") Map<String,Object> getBudget(@RequestParam String month,Authentication a){return Map.of("month",month,"amount",budgets.findByUserIdAndMonthKey(uid(a),month).map(b->b.amount).orElse(BigDecimal.ZERO));}
 @PutMapping("/budget") Map<String,Object> putBudget(@Valid @RequestBody BudgetRequest r,Authentication a){YearMonth.parse(r.month());BudgetEntity b=budgets.findByUserIdAndMonthKey(uid(a),r.month()).orElseGet(BudgetEntity::new);b.user=me(a);b.monthKey=r.month();b.amount=r.amount();budgets.save(b);return Map.of("month",b.monthKey,"amount",b.amount);}
 List<TransactionEntity> all(Long id){return txs.findByUserIdOrderByDateDescIdDesc(id);} BigDecimal sum(List<TransactionEntity> list,String type){return list.stream().filter(t->t.type.equals(type)).map(t->t.amount).reduce(BigDecimal.ZERO,BigDecimal::add);}
 @GetMapping("/dashboard") Map<String,Object> dashboard(@RequestParam String month,Authentication a){YearMonth ym=YearMonth.parse(month);var all=all(uid(a));var cur=all.stream().filter(t->YearMonth.from(t.date).equals(ym)).toList();var cats=cur.stream().filter(t->t.type.equals("EXPENSE")).collect(Collectors.groupingBy(t->t.category,Collectors.reducing(BigDecimal.ZERO,t->t.amount,BigDecimal::add))).entrySet().stream().map(e->Map.of("category",e.getKey(),"amount",e.getValue())).sorted((x,y)->((BigDecimal)y.get("amount")).compareTo((BigDecimal)x.get("amount"))).toList();List<Map<String,Object>> trend=new ArrayList<>();for(int i=5;i>=0;i--){YearMonth m=ym.minusMonths(i);var ts=all.stream().filter(t->YearMonth.from(t.date).equals(m)).toList();trend.add(Map.of("month",m.toString(),"label",m.getMonth().getDisplayName(java.time.format.TextStyle.SHORT,Locale.ENGLISH),"expenses",sum(ts,"EXPENSE"),"income",sum(ts,"INCOME")));}BigDecimal budget=budgets.findByUserIdAndMonthKey(uid(a),month).map(b->b.amount).orElse(BigDecimal.ZERO);return Map.of("month",month,"incomeTotal",sum(cur,"INCOME"),"expenseTotal",sum(cur,"EXPENSE"),"budget",budget,"incomeCount",cur.stream().filter(t->t.type.equals("INCOME")).count(),"expenseCount",cur.stream().filter(t->t.type.equals("EXPENSE")).count(),"categoryTotals",cats,"monthlyTrend",trend);}
 @GetMapping("/insights") List<Map<String,String>> insights(@RequestParam String month,Authentication a){YearMonth ym=YearMonth.parse(month);var all=all(uid(a));var cur=all.stream().filter(t->YearMonth.from(t.date).equals(ym)).toList();var ex=cur.stream().filter(t->t.type.equals("EXPENSE")).toList();List<Map<String,String>> out=new ArrayList<>();if(ex.isEmpty()){out.add(Map.of("label","GETTING STARTED","title","Your first month starts with one entry","message","Add your everyday expenses and income. After a few entries, Ledgerly can point out patterns based on your actual activity.","suggestion","Record transactions as they happen so the month-end picture is useful."));return out;}BigDecimal total=sum(ex,"EXPENSE");var by=ex.stream().collect(Collectors.groupingBy(t->t.category,Collectors.reducing(BigDecimal.ZERO,t->t.amount,BigDecimal::add)));var top=by.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);if(top!=null){int pct=total.signum()==0?0:top.getValue().multiply(BigDecimal.valueOf(100)).divide(total,0,RoundingMode.HALF_UP).intValue();out.add(Map.of("label","CATEGORY PATTERN","title",top.getKey()+" is your largest expense category","message",top.getKey()+" accounts for "+pct+"% of the "+money(total)+" recorded in expenses this month.","suggestion","Review a few purchases in this category and choose a realistic limit for next month."));}var prev=all.stream().filter(t->YearMonth.from(t.date).equals(ym.minusMonths(1))).toList();if(!prev.isEmpty()){BigDecimal old=sum(prev,"EXPENSE");if(old.signum()>0){BigDecimal diff=total.subtract(old).multiply(BigDecimal.valueOf(100)).divide(old,0,RoundingMode.HALF_UP);out.add(Map.of("label","MONTH-ON-MONTH","title",diff.signum()>0?"Spending has increased":"Spending has decreased","message","Your expenses are "+diff.abs()+"% "+(diff.signum()>0?"higher":"lower")+" than last month ("+money(old)+").","suggestion",diff.signum()>0?"Check whether the increase comes from a one-off bill or a repeat habit.":"Notice which choices helped lower spending and keep the ones that work."));}}BigDecimal bud=budgets.findByUserIdAndMonthKey(uid(a),month).map(b->b.amount).orElse(BigDecimal.ZERO);if(bud.signum()>0){BigDecimal pct=total.multiply(BigDecimal.valueOf(100)).divide(bud,0,RoundingMode.HALF_UP);out.add(Map.of("label","BUDGET CHECK","title",total.compareTo(bud)>0?"Your spending is above budget":"Budget progress is "+pct+"%","message","You have spent "+money(total)+" against a monthly budget of "+money(bud)+".","suggestion",total.compareTo(bud)>0?"Review optional spending and adjust next month's budget if the target was unrealistic.":"Use the remaining budget as a guide rather than a target to spend."));}if(out.size()<3){long days=Math.max(1,LocalDate.now().getDayOfMonth());BigDecimal daily=total.divide(BigDecimal.valueOf(days),0,RoundingMode.HALF_UP);out.add(Map.of("label","SPENDING PACE","title","Your current average is "+money(daily)+" per day","message","This is the average expense per calendar day so far this month, based on recorded transactions.","suggestion","Check the pace again near the middle of next month to compare like for like."));}return out;}
 static String money(BigDecimal n){return "₹"+n.setScale(0,RoundingMode.HALF_UP).toPlainString();}
 @GetMapping("/reports") Map<String,Object> report(@RequestParam String month,Authentication a){YearMonth ym=YearMonth.parse(month);var all=all(uid(a));var cur=all.stream().filter(t->YearMonth.from(t.date).equals(ym)).toList();var prev=all.stream().filter(t->YearMonth.from(t.date).equals(ym.minusMonths(1))).toList();BigDecimal ce=sum(cur,"EXPENSE"),pe=sum(prev,"EXPENSE");Object change=pe.signum()==0?null:ce.subtract(pe).multiply(BigDecimal.valueOf(100)).divide(pe,0,RoundingMode.HALF_UP).intValue();Map<String,Object> m=new HashMap<>();m.put("month",month);m.put("previousMonth",ym.minusMonths(1).toString());m.put("currentExpense",ce);m.put("previousExpense",prev.isEmpty()?null:pe);m.put("currentIncome",sum(cur,"INCOME"));m.put("expenseChangePercent",change);return m;}
}
